-- ============================================================================
-- Skolopals — seed data
--
-- Machine-generated by concatenating db/seed/*.sql verbatim. The local-only
-- test accounts file is deliberately excluded.
--
-- Safe for production: CAPS curriculum, the business plan's price list, POPIA
-- consent types and retention periods, assessment domains, expense categories.
-- Every statement is idempotent, so re-running it changes nothing.
--
-- Run AFTER 02_migrations_004_to_023.sql.
-- ============================================================================

begin;

do $guard$
begin
  if not exists (select 1 from public.schema_migrations
                 where version = '20261020000023_backfill_existing_users') then
    raise exception 'Run 02_migrations_004_to_023.sql first - the tables these seeds fill do not exist yet.';
  end if;
end
$guard$;


