insert into public.package_prices (package_code, amount_cents, effective_from)
select v.code, v.cents, date '2026-01-01'
from (values
  ('group_1',        45000),
  ('group_2',        75000),
  ('group_3',        95000),
  ('all_subject',   110000),
  ('homework',       50000),
  ('academic_plus', 125000),
  ('one_on_one_hr',  18000),
